        ]
      },
      center: [-122.447, 37.753],
      zoom: 12,
      pitch: 45,
      bearing: -17
    });

    map.on('load', async () => {
      // -------------------------------------------------
      // 3️⃣  Set up the contour generator
      const demSource = new mlcontour.DemSource({
        url: 'https://tiles.example.com/terrain/{z}/{x}/{y}.png',
        encoding: 'terrarium',
        maxzoom: 12,
        worker: true
      });
      demSource.setupMaplibre(maplibregl);

      // -------------------------------------------------
      // 4️⃣  Add the virtual vector source
      map.addSource('contours', {
        type: 'vector',
        tiles: [
          demSource.contourProtocolUrl({
            thresholds: {
              11: [200, 1000],
              12: [100, 500],
              13: [50, 200],
              14: [20, 100],
              15: [10, 50]
            },
            elevationKey: 'ele',
            levelKey: 'level',
            contourLayer: 'contours'
          })
        ],
        maxzoom: 15
      });

      // -------------------------------------------------
      // 5️⃣  Add line layer
      map.addLayer({
        id: 'contour-lines',
        type: 'line',
        source: 'contours',
        'source-layer': 'contours',
        paint: {
          'line-color': 'rgba(0,0,0,0.6)',
          'line-width': [
            'match',
            ['get', 'level'],
            1, 1.5,
            0, 0.8,
            0.5
          ]
        }
      });

      // -------------------------------------------------
      // 6️⃣  (Optional) Add labels for major contours
      map.addLayer({
        id: 'contour-labels',
        type: 'symbol',
        source: 'contours',
        'source-layer': 'contours',
        filter: ['==', ['get', 'level'], 1],
        layout: {
          'symbol-placement': 'line',
          'text-field': ['to-string', ['get', 'ele']],
          'text-size': 12,
          'text-font': ['Open Sans Bold', 'Arial Unicode MS Bold']
        },
        paint: {
          'text-color': '#222',
          'text-halo-color': '#fff',
          'text-halo-width': 1
        }
      });
    });
  </script>
  <style>
    body { margin:0; padding:0; }
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>
</body>
</html>
```

> **Result:** As you pan/zoom the map, the worker generates vector tiles on-the-fly, and you see crisp contour lines that follow the DEM exactly—no pre-generated contour tileset needed.

